doc.css:
body{margin:0;font-family:"DM Sans",-apple-system,sans-serif;color:#1D1C1A;-webkit-font-smoothing:antialiased}
a{color:#1F6FEB}a:hover{color:#1858C4}
button{font-family:inherit;cursor:pointer}
@keyframes shimmer{0%{background-position:-240px 0}100%{background-position:240px 0}}
.sk{display:inline-block;border-radius:8px;background:linear-gradient(90deg,#EFEDE8 0px,#F8F7F4 80px,#EFEDE8 160px);background-size:480px 100%;animation:shimmer 1.4s linear infinite}
@keyframes spin{to{transform:rotate(360deg)}}.spin{animation:spin .9s linear infinite}
@keyframes pulse{0%,100%{opacity:.45}50%{opacity:1}}.pulse{animation:pulse 1.4s ease-in-out infinite}
@media (prefers-reduced-motion: reduce){.sk,.spin,.pulse{animation:none}}

